package com.greenlink.controller; import com.greenlink.dto.*;import com.greenlink.security.AppUserPrincipal;import com.greenlink.service.UserService;import java.util.Map;import org.bson.types.ObjectId;import org.springframework.http.ResponseEntity;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/users") public class UserController {private final UserService s;public UserController(UserService s){this.s=s;} @PostMapping("/profile-image") public ResponseEntity<?> image(@AuthenticationPrincipal AppUserPrincipal p,@RequestParam("profileImage") MultipartFile file){var r=s.profileImage(new ObjectId(p.getId()),file);return ResponseEntity.ok(Map.of("profileImage",r.profileImage()));} @PutMapping("/profile") public UserView update(@AuthenticationPrincipal AppUserPrincipal p,@RequestBody Map<String,Object> b){return s.update(new ObjectId(p.getId()),(String)b.get("name"),(Boolean)b.get("isProvider"));} @GetMapping("/{id}") public UserView get(@PathVariable String id){return s.publicView(new ObjectId(id));}}
